import json
from pandas import Period

cases = []

def add(freq, label, **kwargs):
    p = Period(freq=freq, **kwargs)
    cases.append({'freq': freq, 'label': label, 'ordinal': int(p.ordinal), 'result': p.strftime(None), 'str': str(p)})

for freq in ['A-DEC', 'A-JUN']:
    for year in [1, 999, 1969, 1970, 2012]:
        add(freq, str(year), year=year)
for freq in ['Q-DEC', 'Q-JUL']:
    for year, quarter in [(1, 1), (999, 4), (1969, 4), (1970, 1), (2012, 2)]:
        add(freq, f'{year}Q{quarter}', year=year, quarter=quarter)
for year, month in [(1, 1), (1, 6), (999, 12), (1969, 12), (1970, 1), (2012, 6)]:
    add('M', f'{year}-{month}', year=year, month=month)
for freq, labels in {
    'W-SUN': ['2012-06-01', '1970-01-01'],
    'B': ['2012-06-01', '1970-01-01'],
    'D': ['2012-06-01'],
    'H': ['2012-06-01 03', '1970-01-01 00'],
    'T': ['2012-06-01 03:04', '1970-01-01 00:00'],
    'S': ['2012-06-01 03:04:05', '1970-01-01 00:00:00'],
    'L': ['2012-06-01 03:04:05.123', '1970-01-01 00:00:00.000'],
    'U': ['2012-06-01 03:04:05.123456', '1970-01-01 00:00:00.000000'],
    'N': ['2012-06-01 03:04:05.123456789', '1970-01-01 00:00:00.000000000'],
}.items():
    for label in labels:
        p = Period(label, freq=freq)
        cases.append({'freq': freq, 'label': label, 'ordinal': int(p.ordinal), 'result': p.strftime(None), 'str': str(p)})
for year, month, day in [(1, 1, 1), (999, 12, 31)]:
    add('D', f'{year}-{month}-{day}', year=year, month=month, day=day)
with open('/workspace/period_reference.json', 'w') as f:
    json.dump(cases, f, indent=2)
print('wrote', len(cases))
